import urllib.request,urllib.parse,json
for cat in ['0','2']:
 params={'Symbol':'فملی','Category':cat,'LetterType':'-1','PageNumber':'1','search':'true','Childs':'false','Mains':'true','Publisher':'false','Audited':'true','NotAudited':'true','Consolidatable':'true','NotConsolidatable':'true'}
 url='https://search.codal.ir/api/search/v2/q?'+urllib.parse.urlencode(params)
 try:
  req=urllib.request.Request(url,headers={'User-Agent':'Mozilla/5.0','Accept':'application/json'})
  d=json.loads(urllib.request.urlopen(req,timeout=20).read().decode('utf-8'))
  print('CATEGORY',cat,'TOTAL',d.get('Total'),'COUNT',len(d.get('Letters',[])))
  for x in d.get('Letters',[])[:12]: print(json.dumps({k:x.get(k) for k in ['TracingNo','Title','LetterCode','PublishDateTime']},ensure_ascii=False))
 except Exception as e: print('CATEGORY',cat,'ERROR',type(e).__name__,str(e)[:300])
